import { NETWORK_ADVANCED_SEARCH_FIELD } from '../../constants/ElementIds';
import { networkStamp } from '../../utils/NetworkProvisioning';
import { repeatTo } from './network.data';

/**
 * Test data for US 14117 "Apply advanced search criteria to networks".
 *
 * The sheet names networks that do not exist here ("Alpha Health Network",
 * code NW-1023, "MedCare"). Following the suite's rule - provision, don't find
 * - each case builds its own network carrying the sheet's name as a prefix,
 * and searches for that. Codes are generated by the application, so the
 * code case searches for the code its own network was given.
 *
 * Verified on the live drawer (2026-10-21): title "Advance Search for
 * Networks"; criteria Network Name / Code (placeholder "e.g. National Pharmacy
 * Network"), Network Type, Status, Approval Status; Cancel and Search buttons
 * and a close icon. The Name / Code field declares no maxlength.
 */

/** Drawer field keys, re-exported so the spec never spells an id segment. */
export const FIELD = NETWORK_ADVANCED_SEARCH_FIELD;

/** A name for a case's own network: the sheet's name plus a unique stamp. */
export const sheetNamed = (sheetName: string): string => `${sheetName} ${networkStamp()}`;

export const SEARCH_CASES = {
  englishName: { azureId: '17730', sheetName: 'Alpha Health Network', term: 'Alpha Health' },
  arabicName: { azureId: '17729', sheetName: 'Alpha Health Network', nameAr: 'شبكة ألفا الصحية' },
  code: { azureId: '17728' },
  combined: { azureId: '17733', sheetName: 'MedCare Network', term: 'Med', type: 'PPO', status: 'Active' },
  prepopulated: { azureId: '17731', sheetName: 'MedCare', type: 'PPO', status: 'Active' },
  pagination: { azureId: '17734', startPage: 5, term: 'Automation Network' },
  // The search runs on the Search click, not as the user types (QA lead, 2026-10-27).
  searchOnClick: { azureId: '17732', term: 'Alpha', settleMs: 1_500 },
  cancelDiscards: { azureId: '17737', applied: 'Automation Network', edited: 'Edited but not applied', type: 'POS', status: 'Expired' },
} as const;

/** Boundary values for the Name / Code criterion (17735). */
export const NAME_CODE_BOUNDARY = {
  azureId: '17735',
  minimum: 'A',
  /** The sheet's example maximum; the field declares none, so it is asserted as a limit. */
  maximum: 100,
  atMaximum: repeatTo('N', 100),
  beyondMaximum: repeatTo('N', 101),
} as const;

/** Hostile input (17736). Each must be treated as plain text and match nothing. */
export const HOSTILE_CASE_ID = '17736';
export const HOSTILE_INPUTS = ['<script>alert(1)</script>', "' ; DROP TABLE networks;--"] as const;

/** What a handled hostile search must never reveal. */
export const SERVER_ERROR_MARKERS = ['StackTrace', 'System.', 'Exception', 'SQL'] as const;

